package com.nextrade.engine.settlement; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record SettlementInstruction(TradeId tradeId,UserId buyer,UserId seller,InstrumentId instrument,Quantity quantity,Price price,Money grossValue,Money fee){public Money buyerCashDebit(){return grossValue.add(fee);}public Money sellerCashCredit(){return grossValue.subtract(fee);}}
